% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"shadedRegion","hex":"E8DEF4","reason":"Identifies the area inside the larger circle and outside the smaller circle"}],"reference":"source page 23, p23-q8-c-diagram"}
\begin{tikzpicture}[x=1cm,y=1cm,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{shadedRegion}{HTML}{E8DEF4}
\coordinate (O) at (0,0);
\coordinate (C) at (0,0.6);
\coordinate (I) at ({cos(45)},{0.6+sin(45)});
\coordinate (B) at (0,-2);
\draw[black,fill=shadedRegion] (O) circle[radius=2];
\draw[black,fill=white] (C) circle[radius=1];
\draw[black] (C) -- (I);
\draw[black] (O) -- (B);
\fill[black] (C) circle[radius=0.045];
\fill[black] (O) circle[radius=0.045];
\path (C) -- (I) node[midway,above left] {$4\text{ cm}$};
\path (O) -- (B) node[midway,right] {$8\text{ cm}$};
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"shadedRegion","hex":"E8DEF4","reason":"Distinguishes shaded sectors from the two unshaded sectors"}],"reference":"source page 23, p23-q8-d-diagram"}
\begin{tikzpicture}[x=1cm,y=1cm,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{shadedRegion}{HTML}{E8DEF4}
\coordinate (O) at (0,0);
\coordinate (R) at (2,0);
\coordinate (U) at ({2*cos(50)},{2*sin(50)});
\coordinate (V) at ({2*cos(120)},{2*sin(120)});
\coordinate (L) at ({2*cos(150)},{2*sin(150)});
\fill[shadedRegion] (O) circle[radius=2];
\fill[white] (O) -- (R) arc[start angle=0,end angle=50,radius=2] -- cycle;
\fill[white] (O) -- (V) arc[start angle=120,end angle=150,radius=2] -- cycle;
\draw[black] (O) circle[radius=2];
\draw[black] (O) -- (R);
\draw[black] (O) -- (U);
\draw[black] (O) -- (V);
\draw[black] (O) -- (L);
\draw[black,line width=0.4pt] (0.8,0) arc[start angle=0,end angle=50,radius=0.8];
\draw[black,line width=0.4pt] ({0.8*cos(120)},{0.8*sin(120)}) arc[start angle=120,end angle=150,radius=0.8];
\path (O) ++(25:1.12) node {$50^\circ$};
\path (O) ++(135:1.15) node {$30^\circ$};
\end{tikzpicture}
